                            skillCommands: {
                                source: string;
                                skill: string;
                                /** @enum {string} */
                                form: "inline" | "block";
                                command: string;
                                /** @description Names $ARGUMENTS, $N or a named $name, which are filled with the text typed after the command before it runs. */
                                usesArguments: boolean;
                            }[];
                            unreadableDeclarations: {
                                path: string;
                                /** @enum {string} */
                                kind: "mcp-server" | "lsp-server" | "monitor";
                                entry?: string;
                            }[];
                            skippedLinks: {
                                path: string;
                                message: string;
                            }[];
                            schedules: {
                                name: string;
                                cron: string | null;
                                permissionMode: components["schemas"]["PermissionMode"];
                                startsEnabled: boolean;
                            }[];
                            secrets: {
                                key: string;
                                required: boolean;
                                description?: string;
                            }[];
                            npmDependencies: {
                                name: string;
                                range: string;
                                optional?: boolean;
                            }[];
                            externalHosts: string[];
                            requires: {
                                type: string;
                                name: string;
                                version?: string;
                                satisfied: boolean;
                            }[];
                            conflicts: {
                                /** @enum {string} */
                                level: "error" | "warning";
                                /** @enum {string} */
                                type: "package-name" | "slot" | "skill-name" | "task-name" | "cron-collision" | "adapter-id";
                                description: string;
                                conflictingPackage?: string;
                            }[];
