    "connectors.createReconciliationPreviews": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": {
                    connectionId: string;
                };
            };
        };
        responses: {
            /** @description Complete immutable grant preview */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        previewId: string;
                        connection: {
                            connectionId: string;
                            toolkit: string;
                            label: string;
                            /** @enum {string} */
                            status: "active" | "expired" | "revoked" | "pending" | "paused";
                            /** @enum {string} */
                            custody: "managed" | "self-host" | "external";
                            /** @enum {string} */
                            reconciliationStatus: "ready" | "migration_needs_reconcile";
                        };
                        candidates: {
                            operationRevisionId: string;
                            toolkit: string;
                            operationSlug: string;
                            toolkitVersion: string;
                            /** @enum {string} */
                            capabilityClassification: "read" | "write" | "destructive";
                            /** @enum {string} */
                            retryPolicy: "never" | "provider_idempotency_key";
                            inputSchema: {
                                [key: string]: unknown;
                            };
                            supported: boolean;
                        }[];
                        agents: {
                            agentId: string;
                            displayName: string;
                        }[];
                        currentGrants: {
                            agentId: string;
                            operationRevisionIds: string[];
                            /** @enum {string} */
                            level?: "read" | "read-write";
                        }[];
                        everyAgent: {
                            available: boolean;
                            operationRevisionIds: string[];
                            /** @enum {string} */
                            level?: "read" | "read-write";
                        };
                        /** @enum {boolean} */
                        catalogComplete: true;
                        /** Format: date-time */
                        createdAt: string;
                        /** Format: date-time */
                        expiresAt: string;
                    };
                };
            };
            /** @description The connection must be reconciled before it can be edited */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
