    "rooms.getEvents": {
        parameters: {
            query?: {
                /** @description Resume cursor; ignored past the end of the log. */
                after?: number | null;
                /** @description Resume token `<roomId>-<epoch>-<generation>-<seq>`. Takes precedence over `after`; a token from another room, another server process, another seq space, or in the older generation-less format falls back to a cold connect. */
                resume?: string;
            };
            header?: never;
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description SSE stream: a RoomSnapshot frame on a cold connect, then RoomEvent frames. A WebSocket upgrade of the same path answers `101` with the identical sequence. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/event-stream": components["schemas"]["RoomSnapshot"] | components["schemas"]["RoomEntryEvent"] | components["schemas"]["RoomSignalEvent"] | components["schemas"]["RoomReactionEvent"] | components["schemas"]["RoomCanvasEvent"] | components["schemas"]["RoomRevisionEvent"] | {
                        /** @enum {string} */
                        type: "canvas_event";
                        scope: string;
                        documentId: string;
                        docSeq: number;
                        incarnation?: {
                            /** @enum {number} */
                            v: 1;
                            documentId: string;
                            /** Format: date-time */
                            physicalOpenedAt: string;
                            /** Format: date-time */
                            channelCreatedAt: string;
                            generation: string;
                        };
                        event: {
                            id: string;
                            type: string;
                            /** @description Finite plain JSON, maximum depth 32; bounded by the document channel envelope limit. */
                            payload?: unknown;
                            /** @enum {string} */
                            direction: "upstream" | "downstream" | "system";
                            /** Format: date-time */
                            receivedAt: string;
                        };
                    } | {
                        /** @enum {string} */
                        type: "canvas_channel_snapshot";
                        scope: string;
                        documentId: string;
                        snapshot: {
                            routing?: {
                                enabled: boolean;
                                approvedEventTypes: string[];
                                destinationLabel: string;
                            };
                            incarnation?: {
                                /** @enum {number} */
                                v: 1;
                                documentId: string;
                                /** Format: date-time */
                                physicalOpenedAt: string;
                                /** Format: date-time */
                                channelCreatedAt: string;
                                generation: string;
                            };
                            /** @description Finite plain JSON state, maximum depth 32 and 256 KiB; separate from document content. */
                            state: {
                                [key: string]: unknown;
                            };
                            stateRev: number;
                            highWatermark: number;
                            retentionFloor: number;
                            receiptRetentionFloor: number;
                            resetRequired: boolean;
                            health: {
                                /** @enum {string} */
                                status: "ready" | "warning" | "closed" | "in_doubt";
                                reasons: string[];
                            };
                            receipts: {
                                receipt: {
                                    id: string;
                                    /** @enum {string} */
                                    status: "recorded" | "duplicate";
                                    docSeq: number;
                                };
                                deliveries: {
                                    eventId: string;
                                    routeId: string;
                                    batchId: string | null;
                                    /** @enum {string} */
                                    status: "saved" | "pending" | "routed" | "waiting" | "accepted" | "turn_started" | "turn_done" | "failed" | "in_doubt" | "expired" | "superseded" | "cancelled" | "handled" | "rejected" | "unavailable";
                                    turnId: string | null;
                                    reason: string | null;
                                    /** Format: date-time */
                                    nextEligibleAt?: string;
                                    /** Format: date-time */
                                    updatedAt: string;
                                    /** @enum {string|null} */
                                    ackOutcome?: "handled" | "rejected" | null;
                                    /** Format: date-time */
                                    acknowledgedAt?: string | null;
                                }[];
                                payloadAvailable?: boolean;
                            }[];
                        };
                    };
                };
            };
            /** @description No such room, or the caller may not see it (an agent sees only its own rooms) */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
